import{_ as s,o as a,c as t,a3 as n}from"./chunks/framework.DhF4LrUq.js";const o="/shipperdog/snapshot/screenshots/console-staged-rollout.png",u=JSON.parse('{"title":"Run a staged tenant rollout","description":"Run a staged tenant rollout - author the plan, advance stage by stage (or on checkpoints), and watch every channel arm.","frontmatter":{"description":"Run a staged tenant rollout - author the plan, advance stage by stage (or on checkpoints), and watch every channel arm."},"headers":[],"relativePath":"how-to/console/staged-rollout.md","filePath":"how-to/console/staged-rollout.md"}'),i={name:"how-to/console/staged-rollout.md"};function r(l,e,h,p,d,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="run-a-staged-tenant-rollout" tabindex="-1">Run a staged tenant rollout <a class="header-anchor" href="#run-a-staged-tenant-rollout" aria-label="Permalink to &quot;Run a staged tenant rollout&quot;">​</a></h1><p>A staged tenant rollout widens a production release across its target tenants in controlled stages — pilot tenants, then 10%, 50%, 100% — with one action that rolls the whole thing back. It is the <em>tenant</em> axis, deliberately distinct from the store-side curves (Apple&#39;s phased-release days, Play&#39;s user-fraction), which the engine drives as its per-channel arms. OTA-channel releases stage on a second axis — devices, not tenants; see <a href="/shipperdog/snapshot/how-to/console/ota-rollouts">run OTA rollouts</a>.</p><p>The staged block renders on the <a href="/shipperdog/snapshot/how-to/console/releases">release dashboard</a> inside the <strong>Distribution</strong> section.</p><p><img src="'+o+`" alt="Staged tenant rollout on the release dashboard"></p><h2 id="author-the-plan" tabindex="-1">Author the plan <a class="header-anchor" href="#author-the-plan" aria-label="Permalink to &quot;Author the plan&quot;">​</a></h2><p>A plan is written <strong>before the release&#39;s ACTIVE crossing</strong> — one plan per release, through the API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/distribution/releases/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$RELEASE_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/staged-rollout?organizationId=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;mode&quot;: &quot;CHECKPOINT&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;stages&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          { &quot;tenants&quot;: [&quot;&lt;pilot-tenant-uuid&gt;&quot;] },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          { &quot;percent&quot;: 10 },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          { &quot;percent&quot;: 50 },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          { &quot;percent&quot;: 100 }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      }&#39;</span></span></code></pre></div><ul><li><strong>Mode</strong> — <code>AUTOMATIC</code> (the policy engine decides between stages) or <code>CHECKPOINT</code> (a Release Manager approves each stage).</li><li><strong>Stages</strong> — each is a percentage of the target population or an explicit tenant list. The final stage must reach every target tenant, and every stage must contain everything the previous one reached — the plan only widens.</li><li>Cohorts are deterministic: the same plan on the same release always resolves the same tenants, ordered by a seeded hash.</li></ul><p>The release&#39;s ACTIVE crossing starts the plan — stage 1 is reached before the first dispatch serves anyone, so the very first distribution already respects the first cohort. A release with no plan dispatches to every target, exactly as before.</p><h2 id="drive-the-stages" tabindex="-1">Drive the stages <a class="header-anchor" href="#drive-the-stages" aria-label="Permalink to &quot;Drive the stages&quot;">​</a></h2><p>On the release dashboard&#39;s staged block you see the status chip (<code>running</code>, <code>complete</code>, <code>rolled back</code>), the mode badge (<em>checkpoint (RM approval)</em> or <em>automatic (policy-gated)</em>), the progress bar with <strong>N of M tenants reached</strong>, and each stage&#39;s line.</p><p>To widen:</p><ol><li>Click <strong>Approve and advance</strong> (checkpoint mode) or <strong>Advance</strong> (automatic mode — available when the policy engine clears it).</li><li>Each advance executes the newly reached delta across every channel the release dispatches on: TestFlight group assignments, the Play user-fraction, the platform&#39;s own download availability. Each arm&#39;s outcome lands on the block&#39;s timeline.</li></ol><h2 id="store-side-curves-ride-along" tabindex="-1">Store-side curves ride along <a class="header-anchor" href="#store-side-curves-ride-along" aria-label="Permalink to &quot;Store-side curves ride along&quot;">​</a></h2><p>Where a channel has its own curve, the plan drives it, and the release dashboard shows the curve&#39;s own controls beside the staged block:</p><ul><li><strong>Phased release (App Store)</strong> — Apple&#39;s fixed 7-day availability curve with <strong>Pause</strong>, <strong>Resume</strong>, and <strong>Halt (release to all)</strong>.</li><li><strong>Staged rollout (Google Play)</strong> — the user-fraction curve with its <strong>Advance</strong> (to a chosen percent), <strong>Halt</strong>, <strong>Resume</strong>, and <strong>Re-apply intent</strong> (re-drives the store after drift) controls.</li></ul><p>A failed store dispatch blocks every staged advancement until it is resolved — the store-side standing surfaces as drift on the channel distribution row.</p><h2 id="roll-the-whole-thing-back" tabindex="-1">Roll the whole thing back <a class="header-anchor" href="#roll-the-whole-thing-back" aria-label="Permalink to &quot;Roll the whole thing back&quot;">​</a></h2><p>Enter the rollback <strong>reason</strong> in the staged block&#39;s field and click <strong>Roll back</strong>. One action: reached TestFlight groups are emptied, the Play fraction halts, Apple&#39;s phased curve halts, the platform&#39;s own availability cuts. The reason is mandatory and the whole timeline records it. See <a href="/shipperdog/snapshot/how-to/console/rollback">roll back a release</a> for the full rollback picture.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">rings and promotion</a> · <a href="/shipperdog/snapshot/how-to/console/rollback">roll back a release</a> · <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout concepts</a></p>`,20)])])}const k=s(i,[["render",r]]);export{u as __pageData,k as default};
